/**
 * @brief  Classify one 63-feature window.
 * @param  features  float[63] in FEATURE_NAMES order
 * @return 0 = noncry, 1 = cry (sklearn forest majority vote; ties -> noncry)
 */
static inline int cry_model_predict(const float *features)
{
    return (int)cry_forest_predict(features, CRY_MODEL_NUM_FEATURES);
}

/**
 * @brief  Classify with tree-vote confidence (Lab 3 wrapper pattern).
 * @param  features       float[63] in FEATURE_NAMES order
 * @param  out_confidence optional; voting confidence 0-100 percent
 * @return CRY_PRED_CRY on strict tree majority, else CRY_PRED_NONCRY
 *         (a 24-vote tie resolves to NONCRY, mirroring sklearn argmax)
 */
static inline cry_class_t cry_model_predict_confidence(const float *features,
                                                       uint8_t *out_confidence)
{
    int votes_cry = 0;
    votes_cry += cry_forest_tree_0(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_1(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_2(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_3(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_4(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_5(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_6(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_7(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_8(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_9(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_10(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_11(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_12(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_13(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_14(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_15(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_16(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_17(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_18(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_19(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_20(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_21(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_22(features, CRY_MODEL_NUM_FEATURES);
    votes_cry += cry_forest_tree_23(features, CRY_MODEL_NUM_FEATURES);

    if (votes_cry * 2 > CRY_MODEL_NUM_TREES) {
        if (out_confidence) {
            *out_confidence = (uint8_t)((votes_cry * 100) / CRY_MODEL_NUM_TREES);
        }
        return CRY_PRED_CRY;
    }
    if (out_confidence) {
        *out_confidence =
            (uint8_t)(((CRY_MODEL_NUM_TREES - votes_cry) * 100) / CRY_MODEL_NUM_TREES);
    }
    return CRY_PRED_NONCRY;
}

